import collections, datetime, hashlib, json, os, pathlib, shutil, subprocess, sys, time

ROOT = pathlib.Path(__file__).resolve().parent / 'pr-list-b-native'
SOURCE = pathlib.Path(__file__).resolve().parent.parent
REAL_GIT = shutil.which('git')
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def git(*args, cwd=SOURCE):
    return subprocess.check_output([REAL_GIT, *args], cwd=cwd, creationflags=0x08000000).decode('utf-8').strip()
def save(path, value): path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')

def prepare():
    ROOT.mkdir(parents=True, exist_ok=False)
    repo=ROOT/'repo'; repo.mkdir()
    git('init', '-q', cwd=repo)
    git('config','remote.origin.url','https://github.com/akiojin/gwt.git',cwd=repo)
    refs=git('for-each-ref','--format=%(objectname) %(refname)','refs/remotes/origin').splitlines()
    # Freeze exact ref/OID input. Object reads use the shared immutable object DB;
    # merge-tree objects and all other writes stay in the fixture repository.
    objects=pathlib.Path(git('rev-parse','--path-format=absolute','--git-common-dir'))/'objects'
    (repo/'.git/objects/info/alternates').write_text(objects.as_posix()+'\n',encoding='utf-8',newline='\n')
    if (objects.parent/'shallow').exists():
        shutil.copyfile(objects.parent/'shallow',repo/'.git/shallow')
    direct=[r for r in refs if not r.endswith('refs/remotes/origin/HEAD')]
    (repo/'.git/packed-refs').write_text('\n'.join(direct)+'\n',encoding='utf-8',newline='\n')
    (repo/'.git/HEAD').write_text(git('rev-parse','origin/develop')+'\n',encoding='utf-8',newline='\n')
    hint=git('symbolic-ref','refs/remotes/origin/HEAD')
    (repo/'.git/refs/remotes/origin').mkdir(parents=True)
    (repo/'.git/refs/remotes/origin/HEAD').write_text('ref: '+hint+'\n',encoding='utf-8',newline='\n')
    history=pathlib.Path(os.environ['USERPROFILE'])/'.gwt/projects/99a8660247f5bc49/pr-inventory-history.json'
    (ROOT/'history-input.json').write_bytes(history.read_bytes())
    cache=history.with_name('pr-inventory-cache.json')
    (ROOT/'cache-input.json').write_bytes(cache.read_bytes())
    save(ROOT/'refs.json',{'head':git('rev-parse','HEAD'),'base':git('rev-parse','origin/develop'),'refs':direct,'default':hint,'objects':str(objects)})
    bin=ROOT/'bin'; bin.mkdir()
    fake='''use std::{env,fs,io::Write,process::ExitCode};
fn main()->ExitCode { let a:Vec<_>=env::args().skip(1).collect();
let log=env::var("B_GH_LOG").unwrap(); writeln!(fs::OpenOptions::new().create(true).append(true).open(log).unwrap(),"{a:?}").unwrap();
if a.starts_with(&["pr".into(),"list".into()]) { println!("[]"); return ExitCode::SUCCESS; }
if a.starts_with(&["api".into(),"rate_limit".into()]) { eprintln!("fixture rate probe unavailable"); return ExitCode::from(1); }
eprintln!("unrecognized fixture gh call: {a:?}"); ExitCode::from(97) }
'''
    (bin/'gh.rs').write_text(fake,encoding='utf-8')
    subprocess.run(['rustc',str(bin/'gh.rs'),'-o',str(bin/'gh.exe')],check=True,creationflags=0x08000000)
    print('prepared',ROOT, 'refs',len(direct),flush=True)

def run(label, exe, params, warm):
    case=ROOT/label; case.mkdir()
    home=case/'home'; project=home/'.gwt/projects/99a8660247f5bc49'; project.mkdir(parents=True)
    assert home.is_relative_to(ROOT) and project.is_relative_to(home)
    shutil.copyfile(ROOT/'history-input.json',project/'pr-inventory-history.json')
    if warm:
        cache=json.loads((ROOT/'cache-input.json').read_text(encoding='utf-8'))
        cache['fetched_at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
        cache['include']={'checks':True,'body':True}
        save(project/'pr-inventory-cache.json',cache)
    env={k:v for k,v in os.environ.items() if not k.startswith(('GWT_','GH_','GITHUB_')) and k not in ('GIT_DIR','GIT_WORK_TREE','GIT_INDEX_FILE')}
    env.update(HOME=str(home),USERPROFILE=str(home),PATH=str(ROOT/'bin')+os.pathsep+os.environ['PATH'],GIT_TRACE2_EVENT=str(case/'git-trace.jsonl'),B_GH_LOG=str(case/'gh.log'))
    assert git('show-ref','--verify','refs/remotes/origin/develop',cwd=ROOT/'repo').split()[0] == json.loads((ROOT/'refs.json').read_text(encoding='utf-8'))['base']
    envelope={'schema_version':1,'operation':'pr.list','params':params}
    save(case/'input.json',envelope)
    # File stdio provides EOF immediately and cannot block on a full output pipe.
    started=time.perf_counter(); first=None; censored=False
    with (case/'input.json').open('rb') as inp,(case/'stdout').open('wb') as out,(case/'stderr').open('wb') as err:
        p=subprocess.Popen([str(exe)],cwd=ROOT/'repo',env=env,stdin=inp,stdout=out,stderr=err,creationflags=0x08000000)
        spawned=time.perf_counter()-started
        print('started',label,'pid',p.pid,flush=True)
        while p.poll() is None:
            if first is None and (case/'stdout').stat().st_size: first=time.perf_counter()-started
            if time.perf_counter()-started>600:
                censored=True; p.kill(); break
            time.sleep(.1)
        p.wait()
    elapsed=time.perf_counter()-started
    text=(case/'stdout').read_text(encoding='utf-8')
    if first is None and text: first=elapsed
    try: response=json.loads(text)
    except ValueError: response=None
    events=[json.loads(x) for x in (case/'git-trace.jsonl').read_text(encoding='utf-8').splitlines()] if (case/'git-trace.jsonl').exists() else []
    starts={e['sid']:e for e in events if e['event']=='start'}
    exits={e['sid']:e for e in events if e['event']=='exit'}
    calls=[{'argv':e['argv'],'time':e['time'],'duration_s':exits.get(sid,{}).get('t_abs'),'exit_code':exits.get(sid,{}).get('code')} for sid,e in starts.items()]
    summary=collections.Counter(c['argv'][1] for c in calls)
    result={'label':label,'source_head':git('rev-parse','HEAD'),'native_sha256':sha(exe),'refs_sha256':sha(ROOT/'refs.json'),'spawn_s':spawned,'stdin':'finite input file with EOF; no writer remains','first_stdout_s_upper_bound':first,'poll_resolution_s':.1,'exit_s':elapsed,'exit_code':p.returncode,'censored':censored,'response':response,'stderr':(case/'stderr').read_text(encoding='utf-8'),'git_calls':calls,'git_counts':dict(summary),'gh_argv':(case/'gh.log').read_text(encoding='utf-8').splitlines() if (case/'gh.log').exists() else [],'history_output_sha256':sha(project/'pr-inventory-history.json')}
    save(case/'result.json',result)
    print(json.dumps({k:result[k] for k in ['label','exit_s','exit_code','censored','git_counts']},ensure_ascii=False),flush=True)

if __name__=='__main__':
    if sys.argv[1]=='prepare': prepare()
    else: run(sys.argv[1],pathlib.Path(sys.argv[2]).resolve(),{'include':[]} if 'include-empty' in sys.argv[1] else {},'warm' in sys.argv[1])
